'use client'

import React, { useTransition } from 'react'
import { toggleTaskCompletion } from '../actions'

export default function TaskList({ initialTasks }: { initialTasks: any[] }) {
    const [pending, startTransition] = useTransition()

    return (
        <div className="p-5 bg-white rounded-3xl border border-[#E4DFEA] shadow-xs space-y-3">
            {initialTasks.map((task: any) => (
                <div key={task.id} className="flex items-center justify-between text-sm py-1.5 border-b border-[#F9F7FB] last:border-0">
                    <span className={task.completed ? "line-through text-[#93859E]" : "text-[#2A2030]"}>
                        {task.title}
                    </span>
                    <button
                        onClick={() => {
                            startTransition(async () => {
                                await toggleTaskCompletion(task.id, task.completed)
                            })
                        }}
                        className={`px-2.5 py-0.5 rounded-full text-[11px] font-medium transition-colors cursor-pointer ${task.completed ? 'bg-[#EBF5ED] text-[#2E6B38] hover:bg-[#d8eade]' : 'bg-[#F4EEF8] text-[#7A508C] hover:bg-[#e6daf0]'
                            }`}
                    >
                        {task.completed ? "Done" : "Pending"}
                    </button>
                </div>
            ))}
        </div>
    )
}